:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #182c2a;
  background: #e9eee7;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 18px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #f8f6ed 0, #e9eee7 65%);
}

.card {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 42px);
  border: 1px solid #d3ddd3;
  border-radius: 24px;
  background: #fffefa;
  box-shadow: 0 20px 60px #243c3018;
}

.header { margin-bottom: 30px; }
.eyebrow { color: #60806d; font-size: .78rem; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 10px 0 8px; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.05; letter-spacing: -.05em; }
.header p { max-width: 390px; margin: 0; color: #62716a; line-height: 1.55; }

.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.field { display: grid; gap: 8px; font-weight: 650; }
.input-wrap { display: flex; align-items: center; gap: 8px; padding: 0 14px; border: 1px solid #cbd6cc; border-radius: 12px; background: #fff; color: #74827a; }
.input-wrap:focus-within { border-color: #34745a; box-shadow: 0 0 0 3px #34745a28; }
input { width: 100%; min-width: 0; padding: 13px 0; border: 0; outline: 0; background: transparent; color: #182c2a; font: inherit; font-variant-numeric: tabular-nums; }
.hint { margin: 10px 0 18px; color: #74827a; font-size: .9rem; }
.error { margin: -6px 0 16px; color: #a33b31; font-weight: 600; }

button { width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 15px 18px; border: 0; border-radius: 12px; background: #245b46; color: #fffefa; font: inherit; font-weight: 700; cursor: pointer; transition: background .15s ease, transform .15s ease, box-shadow .15s ease; }
button:hover { background: #1b4938; box-shadow: 0 6px 16px #245b4630; }
button:active { transform: translateY(1px) scale(.99); }
button:focus-visible { outline: 3px solid #d09a48; outline-offset: 3px; }

.result { margin-top: 26px; padding-top: 24px; border-top: 1px solid #e1e7df; }
.change-total { display: flex; justify-content: space-between; align-items: baseline; color: #62716a; }
.change-total strong { color: #245b46; font-size: 2rem; font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
.breakdown-heading { display: flex; justify-content: space-between; align-items: center; margin: 22px 0 10px; }
h2 { margin: 0; font-size: 1.1rem; }
#piece-count { color: #74827a; font-size: .9rem; }
.breakdown { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 0; padding: 0; list-style: none; }
.breakdown li { display: flex; justify-content: space-between; gap: 8px; padding: 11px 12px; border-radius: 10px; background: #f0f4ed; }
.breakdown li span:last-child { color: #245b46; font-weight: 750; }
.no-change { margin: 12px 0 0; color: #62716a; }
footer { margin-top: 24px; padding-top: 18px; border-top: 1px solid #e1e7df; color: #74827a; font-size: .84rem; line-height: 1.5; }

@media (max-width: 420px) {
  body { padding: 18px 12px; }
  .fields { grid-template-columns: 1fr; gap: 12px; }
}

const form = document.getElementById('change-form');
const priceInput = document.getElementById('price');
const paidInput = document.getElementById('paid');
const error = document.getElementById('error');
const result = document.getElementById('result');
const totalOutput = document.getElementById('change-total');
const pieceCount = document.getElementById('piece-count');
const breakdown = document.getElementById('breakdown');
const noChange = document.getElementById('no-change');

const denominations = [
  { cents: 2000, label: '$20 note' },
  { cents: 1000, label: '$10 note' },
  { cents: 500, label: '$5 note' },
  { cents: 200, label: '$2 note' },
  { cents: 100, label: '$1 coin' },
  { cents: 50, label: '50¢ coin' },
  { cents: 20, label: '20¢ coin' },
  { cents: 10, label: '10¢ coin' },
  { cents: 5, label: '5¢ coin' }
];

function toCents(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount < 0) return null;
  const cents = Math.round(amount * 100);
  return Math.abs(amount * 100 - cents) < 0.000001 && cents % 5 === 0 ? cents : null;
}

function formatMoney(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  error.hidden = true;
  result.hidden = true;

  const price = toCents(priceInput.value);
  const paid = toCents(paidInput.value);
  if (price === null || paid === null) {
    error.textContent = 'Enter valid amounts in 5¢ increments.';
    error.hidden = false;
    (price === null ? priceInput : paidInput).focus();
    return;
  }
  if (paid < price) {
    error.textContent = 'The amount paid must be at least the price.';
    error.hidden = false;
    paidInput.focus();
    return;
  }

  let remaining = paid - price;
  let pieces = 0;
  breakdown.replaceChildren();
  for (const denomination of denominations) {
    const count = Math.floor(remaining / denomination.cents);
    if (count === 0) continue;
    remaining -= count * denomination.cents;
    pieces += count;
    const item = document.createElement('li');
    const label = document.createElement('span');
    const quantity = document.createElement('span');
    label.textContent = denomination.label;
    quantity.textContent = `× ${count}`;
    item.append(label, quantity);
    breakdown.append(item);
  }

  totalOutput.textContent = formatMoney(paid - price);
  pieceCount.textContent = `${pieces} ${pieces === 1 ? 'piece' : 'pieces'}`;
  noChange.hidden = pieces !== 0;
  result.hidden = false;
});
